{
  "packet_id": "H6-T01-3",
  "claim_id": "C058",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C058.component",
    "value": "The trial should be stopped or revised if it requires extra staffing.",
    "scope": "A conditional resource stopping rule, without an exception for otherwise favorable outcomes.",
    "provenance": {
      "refs": [
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly makes requiring extra staffing a trigger for stopping or revising the trial, without a favorable-outcome exception."
    }
  },
  "signal_basis": {
    "component_id": "C058.signal_basis",
    "value": "Prospective trial monitoring includes added workload; the relevant stopping trigger is that the trial requires extra staffing, assessed against the explicit constraint against adding staff.",
    "scope": "The selected trial's staffing requirement; added workload alone need not establish that extra staffing is required.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply workload monitoring, the no-added-staff constraint, and the specific staffing trigger."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C058.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim follows from an explicit resource constraint once its trigger occurs; no unresolved empirical relation is needed."
    }
  },
  "rationale": "Given an established requirement for extra staffing, continuing the trial unchanged would violate the mapping's resource constraint. Stopping or revising it is therefore licensed, even if other outcomes are favorable.",
  "uncertainty": "Whether extra staffing is actually required is assumed for this conditional judgment; merely observing additional workload would not establish the trigger.",
  "anomalies": []
}
